1	package reconcore
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service implements the ReconCore contract on top of a Store. The functional
11	// currency is fixed for the lifetime of the process and is the unit every
12	// journal is balanced in.
13	type Service struct {
14		store              *Store
15		functionalCurrency string
16		clock              func() time.Time
17	}
18	
19	// NewService wires a store, a functional currency and an injectable clock.
20	func NewService(store *Store, functionalCurrency string, clock func() time.Time) (*Service, error) {
21		if store == nil {
22			return nil, InternalError("service requires a store")
23		}
24		code, err := validateCurrency(functionalCurrency, "functional currency", true)
25		if err != nil {
26			return nil, err
27		}
28		if clock == nil {
29			clock = time.Now
30		}
31		return &Service{store: store, functionalCurrency: code, clock: clock}, nil
32	}
33	
34	// FunctionalCurrency reports the reporting currency of this process.
35	func (s *Service) FunctionalCurrency() string { return s.functionalCurrency }
36	
37	func (s *Service) now() string {
38		return s.clock().UTC().Format("2006-01-02T15:04:05Z")
39	}
40	
41	// runIdempotent executes action at most once per key. The first response is
42	// stored and replayed for every later request that carries the same key.
43	func (s *Service) runIdempotent(key, operation string, action func(state *State) (any, error)) (any, error) {
44		if key == "" {
45			return nil, ValidationError("Idempotency-Key header is required")
46		}
47		if len(key) > 200 {
48			return nil, ValidationError("Idempotency-Key must be at most 200 characters")
49		}
50		var response any
51		err := s.store.Update(func(state *State) error {
52			if record, found := state.Idempotency[key]; found {
53				if record.Operation != operation {
54					return ConflictError("idempotency key was already used for another operation")
55				}
56				stored, err := decodeResponse(record.Response)
57				if err != nil {
58					return err
59				}
60				response = stored
61				return nil
62			}
63			value, err := action(state)
64			if err != nil {
65				return err
66			}
67			normalized, err := normalizeResponse(value)
68			if err != nil {
69				return err
70			}
71			encoded, err := encodeResponse(normalized)
72			if err != nil {
73				return err
74			}
75			state.Idempotency[key] = &IdempotencyRecord{
76				Key:       key,
77				Operation: operation,
78				Response:  encoded,
79				CreatedAt: s.now(),
80			}
81			response = normalized
82			return nil
83		})
84		if err != nil {
85			return nil, err
86		}
87		return response, nil
88	}
89	
90	type createAccountRequest struct {
91		ID       string  `json:"id"`
92		Name     string  `json:"name"`
93		Type     string  `json:"type"`
94		ParentID *string `json:"parent_id"`
95		Currency string  `json:"currency"`
96	}
97	
98	// CreateAccount adds one node to the chart of accounts.
99	func (s *Service) CreateAccount(body []byte, key string) (any, error) {
100		var request createAccountRequest
101		if err := decodeObject(body, &request); err != nil {
102			return nil, err
103		}
104		id, err := validateIdentifier(request.ID, "account id")
105		if err != nil {
106			return nil, err
107		}
108		name, err := validateText(request.Name, "name")
109		if err != nil {
110			return nil, err
111		}
112		if name == "" {
113			return nil, ValidationError("name is required")
114		}
115		normalBalance, known := normalBalanceByType[request.Type]
116		if !known {
117			return nil, ValidationError("type must be one of asset, liability, equity, revenue or expense")
118		}
119		currency, err := validateCurrency(request.Currency, "currency", true)
120		if err != nil {
121			return nil, err
122		}
123		var parentID *string
124		if request.ParentID != nil {
125			value, err := validateIdentifier(*request.ParentID, "parent_id")
126			if err != nil {
127				return nil, err
128			}
129			parentID = &value
130		}
131		return s.runIdempotent(key, "create-account:"+id, func(state *State) (any, error) {
132			if _, found := state.Accounts[id]; found {
133				return nil, ConflictError("account %s already exists", id)
134			}
135			if parentID != nil {
136				if _, found := state.Accounts[*parentID]; !found {
137					return nil, ValidationError("parent_id %s does not exist", *parentID)
138				}
139			}
140			account := &Account{
141				ID:            id,
142				Name:          name,
143				Type:          request.Type,
144				ParentID:      parentID,
145				Currency:      currency,
146				NormalBalance: normalBalance,
147				CreatedAt:     s.now(),
148			}
149			state.Accounts[id] = account
150			return account, nil
151		})
152	}
153	
154	// ListAccounts returns the whole chart of accounts as a forest.
155	func (s *Service) ListAccounts() (any, error) {
156		return s.store.View(func(state *State) (any, error) {
157			_, roots := accountTree(state)
158			return map[string]any{"accounts": roots}, nil
159		})
160	}
161	
162	// GetAccount returns one account with its subtree.
163	func (s *Service) GetAccount(id string) (any, error) {
164		return s.store.View(func(state *State) (any, error) {
165			nodes, _ := accountTree(state)
166			node, found := nodes[id]
167			if !found {
168				return nil, NotFoundError("account %s was not found", id)
169			}
170			return node, nil
171		})
172	}
173	
174	// GetBalance derives the account balance at asOf from the journals only.
175	func (s *Service) GetBalance(id, asOf string) (any, error) {
176		if id == "" {
177			return nil, ValidationError("account id is required")
178		}
179		if asOf == "" {
180			return nil, ValidationError("as_of query parameter is required")
181		}
182		date, err := validateDate(asOf, "as_of")
183		if err != nil {
184			return nil, err
185		}
186		return s.store.View(func(state *State) (any, error) {
187			account, found := state.Accounts[id]
188			if !found {
189				return nil, NotFoundError("account %s was not found", id)
190			}
191			return s.computeBalance(state, account, date), nil
192		})
193	}
194	
195	func (s *Service) computeBalance(state *State, account *Account, asOf string) *Balance {
196		balance := &Balance{
197			AccountID:          account.ID,
198			AccountName:        account.Name,
199			AccountType:        account.Type,
200			NormalBalance:      account.NormalBalance,
201			Currency:           account.Currency,
202			FunctionalCurrency: s.functionalCurrency,
203			AsOf:               asOf,
204		}
205		for _, journal := range sortedJournals(state) {
206			if journal.Date > asOf {
207				continue
208			}
209			for _, line := range journal.Lines {
210				if line.AccountID != account.ID {
211					continue
212				}
213				balance.PostingCount++
214				if line.Side == "debit" {
215					balance.DebitMinor += line.AmountMinor
216					balance.FunctionalDebitMinor += line.FunctionalAmountMinor
217				} else {
218					balance.CreditMinor += line.AmountMinor
219					balance.FunctionalCreditMinor += line.FunctionalAmountMinor
220				}
221				if balance.FirstPostingDate == "" || journal.Date < balance.FirstPostingDate {
222					balance.FirstPostingDate = journal.Date
223				}
224				if journal.Date > balance.LastPostingDate {
225					balance.LastPostingDate = journal.Date
226				}
227			}
228		}
229		balance.NetMinor = balance.DebitMinor - balance.CreditMinor
230		balance.FunctionalNetMinor = balance.FunctionalDebitMinor - balance.FunctionalCreditMinor
231		balance.BalanceMinor = balance.NetMinor
232		if account.NormalBalance == "credit" {
233			balance.BalanceMinor = -balance.NetMinor
234		}
235		return balance
236	}
