238	// GetTrialBalance derives a read-only trial balance at asOf from the stored
239	// accounts and immutable journals. It never writes state and is recomputed
240	// from the current ledgers on every call.
241	func (s *Service) GetTrialBalance(asOf string) (any, error) {
242		if asOf == "" {
243			return nil, ValidationError("as_of query parameter is required")
244		}
245		date, err := validateDate(asOf, "as_of")
246		if err != nil {
247			return nil, err
248		}
249		return s.store.View(func(state *State) (any, error) {
250			rows := make(map[string]*TrialBalanceRow, len(state.Accounts))
251			ordered := make([]*TrialBalanceRow, 0, len(state.Accounts))
252			for _, account := range sortedAccounts(state) {
253				row := &TrialBalanceRow{
254					AccountID:   account.ID,
255					AccountName: account.Name,
256					Currency:    account.Currency,
257				}
258				rows[account.ID] = row
259				ordered = append(ordered, row)
260			}
261			for _, journal := range sortedJournals(state) {
262				if journal.Date > date {
263					continue
264				}
265				for _, line := range journal.Lines {
266					row := rows[line.AccountID]
267					if row == nil {
268						return nil, InternalError("journal %s posts to unknown account %s", journal.ID, line.AccountID)
269					}
270					row.PostingCount++
271					if line.Side == "debit" {
272						row.DebitMinor += line.AmountMinor
273						row.FunctionalDebitMinor += line.FunctionalAmountMinor
274					} else {
275						row.CreditMinor += line.AmountMinor
276						row.FunctionalCreditMinor += line.FunctionalAmountMinor
277					}
278				}
279			}
280			report := &TrialBalance{
281				AsOf:               date,
282				FunctionalCurrency: s.functionalCurrency,
283				Accounts:           ordered,
284			}
285			for _, row := range ordered {
286				row.NetMinor = row.DebitMinor - row.CreditMinor
287				row.FunctionalNetMinor = row.FunctionalDebitMinor - row.FunctionalCreditMinor
288				report.PostingCount += row.PostingCount
289				if row.FunctionalNetMinor >= 0 {
290					report.FunctionalDebitTotalMinor += row.FunctionalNetMinor
291				} else {
292					report.FunctionalCreditTotalMinor += -row.FunctionalNetMinor
293				}
294			}
295			report.Status = "balanced"
296			if report.FunctionalDebitTotalMinor != report.FunctionalCreditTotalMinor {
297				report.Status = "unbalanced"
298			}
299			return report, nil
300		})
301	}
302	
303	// GetFinancialStatements derives a read-only balance sheet at asOf and an
304	// income statement over the closed period [periodStart, periodEnd]. It is
305	// recomputed from the stored functional amounts on the immutable journals on
306	// every call, never writes state, creates no vouchers and changes no close.
307	func (s *Service) GetFinancialStatements(asOf, periodStart, periodEnd string) (any, error) {
308		if asOf == "" {
309			return nil, ValidationError("as_of query parameter is required")
310		}
311		asOfDate, err := validateDate(asOf, "as_of")
312		if err != nil {
313			return nil, err
314		}
315		if periodStart == "" {
316			return nil, ValidationError("period_start query parameter is required")
317		}
318		startDate, err := validateDate(periodStart, "period_start")
319		if err != nil {
320			return nil, err
321		}
322		if periodEnd == "" {
323			return nil, ValidationError("period_end query parameter is required")
324		}
325		endDate, err := validateDate(periodEnd, "period_end")
326		if err != nil {
327			return nil, err
328		}
329		if startDate > endDate {
330			return nil, ValidationError("period_start must not be after period_end")
331		}
332		if endDate > asOfDate {
333			return nil, ValidationError("period_end must not be after as_of")
334		}
335		return s.store.View(func(state *State) (any, error) {
336			accounts := sortedAccounts(state)
337	
338			// Functional debit and credit totals per account for the balance
339			// sheet window (through asOf) and the income window (the period).
340			asOfDebit := make(map[string]int64, len(accounts))
341			asOfCredit := make(map[string]int64, len(accounts))
342			periodDebit := make(map[string]int64, len(accounts))
343			periodCredit := make(map[string]int64, len(accounts))
344			for _, account := range accounts {
345				asOfDebit[account.ID] = 0
346				asOfCredit[account.ID] = 0
347				periodDebit[account.ID] = 0
348				periodCredit[account.ID] = 0
349			}
350			for _, journal := range sortedJournals(state) {
351				if journal.Date > asOfDate {
352					continue
353				}
354				inPeriod := journal.Date >= startDate && journal.Date <= endDate
355				for _, line := range journal.Lines {
356					if _, known := asOfDebit[line.AccountID]; !known {
357						return nil, InternalError("journal %s posts to unknown account %s", journal.ID, line.AccountID)
358					}
359					if line.Side == "debit" {
360						asOfDebit[line.AccountID] += line.FunctionalAmountMinor
361						if inPeriod {
362							periodDebit[line.AccountID] += line.FunctionalAmountMinor
363						}
364					} else {
365						asOfCredit[line.AccountID] += line.FunctionalAmountMinor
366						if inPeriod {
367							periodCredit[line.AccountID] += line.FunctionalAmountMinor
368						}
369					}
370				}
371			}
372	
373			balanceSheet := &BalanceSheet{
374				Assets:      []*FinancialStatementAccount{},
375				Liabilities: []*FinancialStatementAccount{},
376				Equity:      []*FinancialStatementAccount{},
377			}
378			incomeStatement := &IncomeStatement{
379				Revenue:  []*FinancialStatementAccount{},
380				Expenses: []*FinancialStatementAccount{},
381			}
382			for _, account := range accounts {
383				row := &FinancialStatementAccount{
384					AccountID:   account.ID,
385					AccountName: account.Name,
386					ParentID:    account.ParentID,
387					Currency:    account.Currency,
388				}
389				debitNormal := account.NormalBalance == "debit"
390				balance := asOfDebit[account.ID] - asOfCredit[account.ID]
391				if !debitNormal {
392					balance = -balance
393				}
394				row.FunctionalBalanceMinor = balance
395				switch account.Type {
396				case "asset":
397					balanceSheet.Assets = append(balanceSheet.Assets, row)
398					balanceSheet.AssetsTotalMinor += balance
399				case "liability":
400					balanceSheet.Liabilities = append(balanceSheet.Liabilities, row)
401					balanceSheet.LiabilitiesTotalMinor += balance
402				case "equity":
403					balanceSheet.Equity = append(balanceSheet.Equity, row)
404					balanceSheet.EquityTotalMinor += balance
405				case "revenue":
406					incomeStatement.Revenue = append(incomeStatement.Revenue, periodRow(account, periodCredit, periodDebit))
407					incomeStatement.RevenueTotalMinor += periodCredit[account.ID] - periodDebit[account.ID]
408				case "expense":
409					incomeStatement.Expenses = append(incomeStatement.Expenses, periodRow(account, periodDebit, periodCredit))
410					incomeStatement.ExpensesTotalMinor += periodDebit[account.ID] - periodCredit[account.ID]
411				}
412			}
413			incomeStatement.NetIncomeMinor = incomeStatement.RevenueTotalMinor - incomeStatement.ExpensesTotalMinor
414	
415			// Equity through as_of includes the income earned through as_of, so
416			// the accounting equation balances even before the books are closed.
417			var revenueThroughAsOf, expensesThroughAsOf int64
418			for _, account := range accounts {
419				switch account.Type {
420				case "revenue":
421					revenueThroughAsOf += asOfCredit[account.ID] - asOfDebit[account.ID]
422				case "expense":
423					expensesThroughAsOf += asOfDebit[account.ID] - asOfCredit[account.ID]
424				}
425			}
426			balanceSheet.EquityTotalMinor += revenueThroughAsOf - expensesThroughAsOf
427			balanceSheet.BalanceCheckMinor = balanceSheet.AssetsTotalMinor -
428				balanceSheet.LiabilitiesTotalMinor - balanceSheet.EquityTotalMinor
429			balanceSheet.Status = "balanced"
430			if balanceSheet.BalanceCheckMinor != 0 {
431				balanceSheet.Status = "unbalanced"
432			}
433			return &FinancialStatements{
434				AsOf:               asOfDate,
435				PeriodStart:        startDate,
436				PeriodEnd:          endDate,
437				FunctionalCurrency: s.functionalCurrency,
438				BalanceSheet:       balanceSheet,
439				IncomeStatement:    incomeStatement,
440			}, nil
441		})
442	}
443	
444	// periodRow builds the income-statement row for one account from the functional
445	// totals of journals dated inside the report period; positive holds the side
446	// that increases the account type (debits for expenses, credits for revenue)
447	// and negative the opposite side.
448	func periodRow(account *Account, positive, negative map[string]int64) *FinancialStatementAccount {
449		return &FinancialStatementAccount{
450			AccountID:              account.ID,
451			AccountName:            account.Name,
452			ParentID:               account.ParentID,
453			Currency:               account.Currency,
454			FunctionalBalanceMinor: positive[account.ID] - negative[account.ID],
455		}
456	}
