465	// CreateRate stores one exchange rate snapshot.
466	func (s *Service) CreateRate(body []byte, key string) (any, error) {
467		var request createRateRequest
468		if err := decodeObject(body, &request); err != nil {
469			return nil, err
470		}
471		base, err := validateCurrency(request.Base, "base", true)
472		if err != nil {
473			return nil, err
474		}
475		quote, err := validateCurrency(request.Quote, "quote", true)
476		if err != nil {
477			return nil, err
478		}
479		if base == quote {
480			return nil, ValidationError("base and quote must be different currencies")
481		}
482		date, err := validateDate(request.Date, "date")
483		if err != nil {
484			return nil, err
485		}
486		numerator, denominator, err := parseRateFraction(request.Rate, "rate")
487		if err != nil {
488			return nil, err
489		}
490		return s.runIdempotent(key, fmt.Sprintf("create-rate:%s/%s/%s", base, quote, date), func(state *State) (any, error) {
491			for _, existing := range state.Rates {
492				if existing.Base == base && existing.Quote == quote && existing.Date == date {
493					return nil, ConflictError("a %s/%s rate for %s already exists", base, quote, date)
494				}
495			}
496			rate := &Rate{
497				Base:        base,
498				Quote:       quote,
499				Date:        date,
500				Rate:        request.Rate,
501				Numerator:   numerator,
502				Denominator: denominator,
503				CreatedAt:   s.now(),
504			}
505			state.Rates = append(state.Rates, rate)
506			return rate, nil
507		})
508	}
