917	// resolveRate returns the exact fraction that converts one minor unit of
918	// currency into the functional currency for the given date.
919	func (s *Service) resolveRate(state *State, currency, date, declared, field string) (int64, int64, string, error) {
920		if currency == s.functionalCurrency {
921			if declared == "" || declared == "1" {
922				return 1, 1, "identity", nil
923			}
924			numerator, denominator, err := parseRateFraction(declared, field)
925			if err != nil {
926				return 0, 0, "", err
927			}
928			if numerator != denominator {
929				return 0, 0, "", ValidationError(
930					"%s must be omitted or exactly 1 because %s is the functional currency",
931					field, currency,
932				)
933			}
934			return 1, 1, "identity", nil
935		}
936		if declared != "" {
937			numerator, denominator, err := parseRateFraction(declared, field)
938			if err != nil {
939				return 0, 0, "", err
940			}
941			return numerator, denominator, "declared", nil
942		}
943		if direct := latestRate(state, currency, s.functionalCurrency, date); direct != nil {
944			return direct.Numerator, direct.Denominator, "snapshot:" + direct.Date, nil
945		}
946		if inverse := latestRate(state, s.functionalCurrency, currency, date); inverse != nil {
947			return inverse.Denominator, inverse.Numerator, "snapshot-inverse:" + inverse.Date, nil
948		}
949		return 0, 0, "", ValidationError(
950			"no %s/%s exchange rate snapshot exists on or before %s",
951			currency, s.functionalCurrency, date,
952		)
953	}
