1162	// CreateResolution records the immutable human disposition of one frozen
1163	// difference. The difference is addressed by its 1-based index inside the
1164	// frozen reconciliation, holds at most one resolution, and is snapshotted
1165	// into the resolution so later activity can never change what was reviewed.
1166	func (s *Service) CreateResolution(reconciliationID string, body []byte, key string) (any, error) {
1167		var request createResolutionRequest
1168		if err := decodeObject(body, &request); err != nil {
1169			return nil, err
1170		}
1171		id, err := validateIdentifier(request.ID, "resolution id")
1172		if err != nil {
1173			return nil, err
1174		}
1175		if request.DifferenceIndex < 1 {
1176			return nil, ValidationError("difference_index must be a positive integer starting at 1")
1177		}
1178		if request.Disposition != "accepted" && request.Disposition != "resolved" {
1179			return nil, ValidationError("disposition must be accepted or resolved")
1180		}
1181		reason := strings.TrimSpace(request.Reason)
1182		if reason == "" {
1183			return nil, ValidationError("reason must not be empty")
1184		}
1185		if _, err := validateText(reason, "reason"); err != nil {
1186			return nil, err
1187		}
1188		return s.runIdempotent(key, "create-resolution:"+reconciliationID+":"+id, func(state *State) (any, error) {
1189			reconciliation, found := state.Reconciliations[reconciliationID]
1190			if !found {
1191				return nil, NotFoundError("reconciliation %s was not found", reconciliationID)
1192			}
1193			if request.DifferenceIndex > len(reconciliation.Differences) {
1194				return nil, ValidationError(
1195					"difference_index %d is out of range: reconciliation %s has %d differences",
1196					request.DifferenceIndex, reconciliationID, len(reconciliation.Differences),
1197				)
1198			}
1199			if _, found := state.Resolutions[id]; found {
1200				return nil, ConflictError("resolution %s already exists", id)
1201			}
1202			for _, existing := range state.Resolutions {
1203				if existing.ReconciliationID == reconciliationID && existing.DifferenceIndex == request.DifferenceIndex {
1204					return nil, ConflictError(
1205						"difference %d of reconciliation %s already has resolution %s",
1206						request.DifferenceIndex, reconciliationID, existing.ID,
1207					)
1208				}
1209			}
1210			resolution := &Resolution{
1211				ID:               id,
1212				ReconciliationID: reconciliationID,
1213				DifferenceIndex:  request.DifferenceIndex,
1214				Disposition:      request.Disposition,
1215				Reason:           reason,
1216				Difference:       copyDifference(reconciliation.Differences[request.DifferenceIndex-1]),
1217				CreatedAt:        s.now(),
1218			}
1219			state.Resolutions[id] = resolution
1220			return resolution, nil
1221		})
1222	}
