1224	// ListResolutions reports the review progress of one reconciliation. The
1225	// counts are derived from the frozen differences, so they never change when
1226	// new journals, statements or reconciliations appear later.
1227	func (s *Service) ListResolutions(reconciliationID string) (any, error) {
1228		return s.store.View(func(state *State) (any, error) {
1229			reconciliation, found := state.Reconciliations[reconciliationID]
1230			if !found {
1231				return nil, NotFoundError("reconciliation %s was not found", reconciliationID)
1232			}
1233			records := []*Resolution{}
1234			for _, resolution := range state.Resolutions {
1235				if resolution.ReconciliationID == reconciliationID {
1236					records = append(records, resolution)
1237				}
1238			}
1239			sort.Slice(records, func(left, right int) bool {
1240				return records[left].DifferenceIndex < records[right].DifferenceIndex
1241			})
1242			differenceCount := len(reconciliation.Differences)
1243			remaining := differenceCount - len(records)
1244			status := "pending"
1245			if remaining == 0 {
1246				status = "completed"
1247			}
1248			return map[string]any{
1249				"reconciliation_id": reconciliationID,
1250				"records":           records,
1251				"difference_count":  differenceCount,
1252				"disposed_count":    len(records),
1253				"remaining_count":   remaining,
1254				"review_status":     status,
1255			}, nil
1256		})
1257	}
