1259	// ledgerEntry is one journal line seen from the ledger side of a
1260	// reconciliation. AmountMinor is signed with debits positive.
1261	type ledgerEntry struct {
1262		ID          string
1263		Date        string
1264		AmountMinor int64
1265		Reference   string
1266	}
1267	
1268	func ledgerEntries(state *State, accountID string, period Period) []*ledgerEntry {
1269		entries := []*ledgerEntry{}
1270		for _, journal := range sortedJournals(state) {
1271			if journal.Date < period.Start || journal.Date > period.End {
1272				continue
1273			}
1274			for _, line := range journal.Lines {
1275				if line.AccountID != accountID {
1276					continue
1277				}
1278				amount := line.AmountMinor
1279				if line.Side == "credit" {
1280					amount = -amount
1281				}
1282				entries = append(entries, &ledgerEntry{
1283					ID:          fmt.Sprintf("%s#%d", journal.ID, line.Index),
1284					Date:        journal.Date,
1285					AmountMinor: amount,
1286					Reference:   line.Reference,
1287				})
1288			}
1289		}
1290		return entries
1291	}
1292	
1293	var differenceOrder = map[string]int{
1294		"timing":               0,
1295		"amount_mismatch":      1,
1296		"missing_in_ledger":    2,
1297		"missing_in_statement": 3,
1298	}
1299	
1300	// computeReconciliation matches statement lines to ledger lines in three
1301	// deterministic tiers and classifies everything that stays unmatched.
1302	func (s *Service) computeReconciliation(state *State, statement *Statement, id, createdAt string) (*Reconciliation, error) {
1303		lines := make([]*StatementLine, 0, len(statement.Lines))
1304		lines = append(lines, statement.Lines...)
1305		sort.Slice(lines, func(left, right int) bool { return lines[left].ID < lines[right].ID })
1306	
1307		entries := ledgerEntries(state, statement.AccountID, statement.Period)
1308		sort.Slice(entries, func(left, right int) bool { return entries[left].ID < entries[right].ID })
1309	
1310		statementUsed := make([]bool, len(lines))
1311		ledgerUsed := make([]bool, len(entries))
1312		differences := []*Difference{}
1313		matched := 0
1314		match := func(statementIndex, ledgerIndex int, difference *Difference) {
1315			statementUsed[statementIndex] = true
1316			ledgerUsed[ledgerIndex] = true
1317			matched++
1318			if difference != nil {
1319				differences = append(differences, difference)
1320			}
1321		}
1322	
1323		// Tier 1: same signed amount and same date.
1324		for index, line := range lines {
1325			for other, entry := range entries {
1326				if ledgerUsed[other] {
1327					continue
1328				}
1329				if entry.AmountMinor == line.AmountMinor && entry.Date == line.Date {
1330					match(index, other, nil)
1331					break
1332				}
1333			}
1334		}
1335	
1336		// Tier 2: same signed amount, different date, so it only differs in timing.
1337		for index, line := range lines {
1338			if statementUsed[index] {
1339				continue
1340			}
1341			for other, entry := range entries {
1342				if ledgerUsed[other] || entry.AmountMinor != line.AmountMinor {
1343					continue
1344				}
1345				statementAmount := line.AmountMinor
1346				ledgerAmount := entry.AmountMinor
1347				match(index, other, &Difference{
1348					Type:                 "timing",
1349					Detail:               "the amounts agree but the ledger date differs from the statement date",
1350					StatementLineID:      line.ID,
1351					LedgerLineID:         entry.ID,
1352					StatementDate:        line.Date,
1353					LedgerDate:           entry.Date,
1354					StatementAmountMinor: &statementAmount,
1355					LedgerAmountMinor:    &ledgerAmount,
1356				})
1357				break
1358			}
1359		}
1360	
1361		// Tier 3: same non-empty reference but a different amount.
1362		for index, line := range lines {
1363			if statementUsed[index] || line.Reference == "" {
1364				continue
1365			}
1366			for other, entry := range entries {
1367				if ledgerUsed[other] || entry.Reference == "" || entry.Reference != line.Reference {
1368					continue
1369				}
1370				statementAmount := line.AmountMinor
1371				ledgerAmount := entry.AmountMinor
1372				match(index, other, &Difference{
1373					Type:                 "amount_mismatch",
1374					Detail:               fmt.Sprintf("reference %s appears on both sides with different amounts", line.Reference),
1375					StatementLineID:      line.ID,
1376					LedgerLineID:         entry.ID,
1377					StatementDate:        line.Date,
1378					LedgerDate:           entry.Date,
1379					StatementAmountMinor: &statementAmount,
1380					LedgerAmountMinor:    &ledgerAmount,
1381					DifferenceMinor:      statementAmount - ledgerAmount,
1382				})
1383				break
1384			}
1385		}
1386	
1387		// Everything still unmatched is missing on one side.
1388		for index, line := range lines {
1389			if statementUsed[index] {
1390				continue
1391			}
1392			amount := line.AmountMinor
1393			differences = append(differences, &Difference{
1394				Type:                 "missing_in_ledger",
1395				Detail:               "the statement line has no journal line in the period",
1396				StatementLineID:      line.ID,
1397				StatementDate:        line.Date,
1398				StatementAmountMinor: &amount,
1399				DifferenceMinor:      amount,
1400			})
1401		}
1402		for index, entry := range entries {
1403			if ledgerUsed[index] {
1404				continue
1405			}
1406			amount := entry.AmountMinor
1407			differences = append(differences, &Difference{
1408				Type:              "missing_in_statement",
1409				Detail:            "the journal line has no statement line in the period",
1410				LedgerLineID:      entry.ID,
1411				LedgerDate:        entry.Date,
1412				LedgerAmountMinor: &amount,
1413				DifferenceMinor:   -amount,
1414			})
1415		}
1416	
1417		sort.SliceStable(differences, func(left, right int) bool {
1418			a, b := differences[left], differences[right]
1419			if differenceOrder[a.Type] != differenceOrder[b.Type] {
1420				return differenceOrder[a.Type] < differenceOrder[b.Type]
1421			}
1422			if a.StatementLineID != b.StatementLineID {
1423				return a.StatementLineID < b.StatementLineID
1424			}
1425			return a.LedgerLineID < b.LedgerLineID
1426		})
1427	
1428		var ledgerNet int64
1429		for _, entry := range entries {
1430			ledgerNet += entry.AmountMinor
1431		}
1432		statementNet := statement.ClosingBalanceMinor - statement.OpeningBalanceMinor
1433	
1434		summary := DifferenceSummary{}
1435		var explained int64
1436		for _, difference := range differences {
1437			explained += difference.DifferenceMinor
1438			switch difference.Type {
1439			case "timing":
1440				summary.Timing++
1441			case "amount_mismatch":
1442				summary.AmountMismatch++
1443			case "missing_in_ledger":
1444				summary.MissingInLedger++
1445			case "missing_in_statement":
1446				summary.MissingInStatement++
1447			default:
1448				return nil, InternalError("reconciliation produced the unknown difference type %s", difference.Type)
1449			}
1450		}
1451		if 2*matched+summary.MissingInLedger+summary.MissingInStatement != len(lines)+len(entries) {
1452			return nil, InternalError("reconciliation differences are not mutually exclusive and complete")
1453		}
1454		if explained != statementNet-ledgerNet {
1455			return nil, InternalError("reconciliation differences do not add up to the period difference")
1456		}
1457	
1458		status := "balanced"
1459		if len(differences) > 0 {
1460			status = "differences_found"
1461		}
1462		return &Reconciliation{
1463			ID:                 id,
1464			StatementID:        statement.ID,
1465			AccountID:          statement.AccountID,
1466			Currency:           statement.Currency,
1467			FunctionalCurrency: s.functionalCurrency,
1468			Period:             statement.Period,
1469			Status:             status,
1470			MatchedCount:       matched,
1471			StatementLineCount: len(lines),
1472			LedgerLineCount:    len(entries),
1473			StatementNetMinor:  statementNet,
1474			LedgerNetMinor:     ledgerNet,
1475			DifferenceMinor:    statementNet - ledgerNet,
1476			Summary:            summary,
1477			Differences:        differences,
1478			CreatedAt:          createdAt,
1479		}, nil
1480	}
1481	
1482	func sortedAccounts(state *State) []*Account {
1483		accounts := make([]*Account, 0, len(state.Accounts))
1484		for _, account := range state.Accounts {
1485			accounts = append(accounts, account)
1486		}
1487		sort.Slice(accounts, func(left, right int) bool { return accounts[left].ID < accounts[right].ID })
1488		return accounts
1489	}
1490	
1491	func sortedJournals(state *State) []*Journal {
1492		journals := make([]*Journal, 0, len(state.Journals))
1493		for _, journal := range state.Journals {
1494			journals = append(journals, journal)
1495		}
1496		sort.Slice(journals, func(left, right int) bool {
1497			if journals[left].Date != journals[right].Date {
1498				return journals[left].Date < journals[right].Date
1499			}
1500			return journals[left].ID < journals[right].ID
1501		})
1502		return journals
1503	}
1504	
1505	func sortedRates(state *State) []*Rate {
1506		rates := make([]*Rate, 0, len(state.Rates))
1507		rates = append(rates, state.Rates...)
1508		sort.Slice(rates, func(left, right int) bool {
1509			a, b := rates[left], rates[right]
1510			if a.Base != b.Base {
1511				return a.Base < b.Base
1512			}
1513			if a.Quote != b.Quote {
1514				return a.Quote < b.Quote
1515			}
1516			return a.Date < b.Date
1517		})
1518		return rates
1519	}
1520	
1521	func accountTree(state *State) (map[string]*AccountNode, []*AccountNode) {
1522		nodes := map[string]*AccountNode{}
1523		for _, account := range state.Accounts {
1524			nodes[account.ID] = &AccountNode{Account: *account, Children: []*AccountNode{}}
1525		}
1526		roots := []*AccountNode{}
1527		for _, account := range sortedAccounts(state) {
1528			node := nodes[account.ID]
1529			if account.ParentID == nil {
1530				roots = append(roots, node)
1531				continue
1532			}
1533			parent, found := nodes[*account.ParentID]
1534			if !found {
1535				roots = append(roots, node)
1536				continue
1537			}
1538			parent.Children = append(parent.Children, node)
1539		}
1540		return nodes, roots
1541	}
1542	
1543	// latestRate returns the most recent snapshot for one direction that is
1544	// effective on the given date.
1545	func latestRate(state *State, base, quote, asOf string) *Rate {
1546		var best *Rate
1547		for _, rate := range state.Rates {
1548			if rate.Base != base || rate.Quote != quote || rate.Date > asOf {
1549				continue
1550			}
1551			if best == nil || rate.Date > best.Date {
1552				best = rate
1553			}
1554		}
1555		return best
1556	}
1557

